from exo.libs.memories import DRAM
# Import scheduling API (required by the driver infrastructure even if we
# perform manual tiling rather than calling scheduling primitives here).
from exo.API_scheduling import *

# Tiling parameters tuned for cache / SIMD on a modern x86-64 CPU.
TI = 32   # tile size in i  (rows of C)
TJ = 32   # tile size in j  (cols of C)
TK = 32   # tile size in k  (columns of A,B / rank-2k dimension)

@proc
def kernel_syr2k(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
    B: DATA_TYPE[n, m] @ DRAM,
):
    # ------------------------------------------------------------------
    # Optimized SYR2K kernel.
    #
    # Mathematical operation (lower triangle only, j <= i):
    #
    #   C[i,j] = beta * C[i,j] +
    #            alpha * sum_{k=0..m-1}(
    #                      A[j,k] * B[i,k] +
    #                      B[j,k] * A[i,k])
    #
    # for all 0 <= j <= i < n.  Elements with j > i are left unchanged.
    #
    # This procedure implements the same update but:
    #   - Uses two explicit phases:
    #       (1) scale C by beta in the lower triangle,
    #       (2) perform the rank‑2k update,
    #   - Tiles the iteration space in i, j, and k
    #   - Hoists multiplications by alpha for A[i,k] and B[i,k]
    #     into small temporaries reused across many j.
    # ------------------------------------------------------------------

