    # Phase 1: scale C by beta
    # ----------------------------
    # Only the lower triangle (j <= i) is scaled, matching the original
    # algorithm.  We block over i and j for cache locality; tiles that
    # lie entirely above the diagonal are skipped by the j <= i guard.
    for II in seq(0, (n + TI - 1) / TI):
        for JJ in seq(0, (n + TJ - 1) / TJ):
            for i in seq(0, TI):
                # Global row index.
                if II * TI + i < n:
                    for j in seq(0, TJ):
                        # Global column index.
                        if JJ * TJ + j < n and JJ * TJ + j <= II * TI + i:
                            C[II * TI + i, JJ * TJ + j] = beta * C[II * TI + i, JJ * TJ + j]

