    #   - tA[k_t] = alpha * A[i, k_g] streams along row i of A
    #   - tB[k_t] = alpha * B[i, k_g] streams along row i of B
    #   - inner j/k_t loops stream along rows j of A and B and row i of C.
    for KK in seq(0, (m + TK - 1) / TK):
